// Prefer the pre-resolved direct CDN URL (CORS-clean, no redirect); fall back to the
// Special:FilePath redirect for any file added since the map was last generated.
export function commonsThumb(file, width = 900) {
  return (
    COMMONS_THUMBS[file.replace(/_/g, " ")] ??
    `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=${width}`
  );
}

// An entry is either a Wikimedia Commons file (`file`) or a direct URL from another
// free-license source (`url` + `source`, e.g. Unsplash, the Met, Cooper Hewitt).
export function photoUrl(entry) {
  return entry.url ?? commonsThumb(entry.file);
}

// Moved to lib/imageUrls.js so components can use them without loading this file; re-exported
// here so existing imports keep working.
export { cardImage, fallbackToFull } from "../lib/imageUrls.js";

export function photoSource(entry) {
  return entry.source ?? "Wikimedia Commons";
}

// Every photo links back to the page it comes from. Entries harvested from the web carry an
// explicit `sourceUrl`; for the older library sources the page is derivable from the image URL
// itself (the Commons file page, the Flickr photo id, the Pexels photo id), so we build it here
// instead of storing it twice.
export function photoPage(entry) {
  if (entry.sourceUrl) return entry.sourceUrl;
  if (entry.file) return `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(entry.file.replace(/ /g, "_"))}`;
  const url = entry.url ?? "";
  const flickr = /live\.staticflickr\.com\/\d+\/(\d+)_/.exec(url);
  if (flickr) return `https://www.flickr.com/photo.gne?id=${flickr[1]}`;
  const pexels = /images\.pexels\.com\/photos\/(\d+)\//.exec(url);
  if (pexels) return `https://www.pexels.com/photo/${pexels[1]}/`;
  return url || null;
}
